import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Container, Row, Col, Card, Form, Button } from 'react-bootstrap';

const ShopPage = () => {
  const navigate = useNavigate();
  const [quantities, setQuantities] = useState({});
  const [showCart, setShowCart] = useState(false);

  // Focused exclusively on Tilapia products
  const tilapiaProducts = [
    { id: 1, name: "Fresh Tilapia", price: 12.99, unit: "kg", description: "Freshly caught from Lake Victoria" },
    { id: 2, name: "Premium Tilapia Fillets", price: 18.99, unit: "kg", description: "Boneless, skinless fillets" },
    { id: 3, name: "Smoked Tilapia", price: 15.99, unit: "kg", description: "Traditional smoked flavor" },
    { id: 4, name: "Tilapia Steaks", price: 14.99, unit: "kg", description: "Ready-to-grill portions" },
    { id: 5, name: "Whole Frozen Tilapia", price: 10.99, unit: "kg", description: "Flash frozen for freshness" },
    { id: 6, name: "Value Pack Tilapia", price: 9.99, unit: "kg", description: "5kg minimum purchase" },
  ];

  const handleQuantityChange = (id, value) => {
    setQuantities({
      ...quantities,
      [id]: value
    });
  };

  const handleAddToCart = (product) => {
    if (!quantities[product.id] || quantities[product.id] <= 0) {
      alert(`Please enter a valid quantity for ${product.name}`);
      return;
    }
    
    alert(`Added ${quantities[product.id]}kg of ${product.name} to cart!`);
    // In a real app, you would add to cart context/reducer here
  };

  return (
    <Container className="py-5">
      <Row>
        <Col lg={10} className="mx-auto">
          <h1 className="display-4 text-center mb-4">Fresh Tilapia</h1>
          <p className="lead text-center mb-5">
            Premium tilapia harvested daily by our women-led fishing communities. 
            All products sold by weight in kilograms.
          </p>
          
          <Row className="mt-4">
            {tilapiaProducts.map((product) => (
              <Col key={product.id} md={6} lg={4} className="mb-4">
                <Card className="h-100 border-0 shadow-sm">
                  <div 
                    className="product-image bg-light d-flex align-items-center justify-content-center"
                    style={{ height: '200px' }}
                  >
                    <div className="text-center">
                      <i className="bi bi-fish" style={{ fontSize: '3rem', color: '#1e62d0' }}></i>
                      <p className="mt-2 fw-bold">{product.name}</p>
                    </div>
                  </div>
                  <Card.Body className="d-flex flex-column">
                    <div className="mb-3">
                      <h5 className="text-primary">{product.name}</h5>
                      <p className="text-muted mb-1">{product.description}</p>
                      <p className="fw-bold mb-2">${product.price.toFixed(2)} per kg</p>
                    </div>
                    
                    <div className="mt-auto">
                      <Form.Group className="mb-3">
                        <Form.Label>Quantity (kg)</Form.Label>
                        <Form.Control 
                          type="number" 
                          min="0.1"
                          step="0.1"
                          value={quantities[product.id] || ''}
                          onChange={(e) => handleQuantityChange(product.id, e.target.value)}
                          placeholder="Enter kg"
                        />
                      </Form.Group>
                      <Button 
                        variant="primary" 
                        className="w-100"
                        onClick={() => handleAddToCart(product)}
                      >
                        Add to Cart
                      </Button>
                    </div>
                  </Card.Body>
                </Card>
              </Col>
            ))}
          </Row>
          
          <div className="mt-5 p-4 bg-light rounded text-center">
            <h3 className="mb-3">Community Supported Fisheries</h3>
            <p className="mb-4">
              Every kilogram purchased directly supports our women fishers and their families. 
              Subscribe for weekly fresh tilapia deliveries at special discounted prices!
            </p>
            
            <div className="d-flex justify-content-center gap-3">
              <Button 
                variant="success"
                onClick={() => navigate('/join')}
                className="px-4 py-2"
              >
                Subscribe Now
              </Button>
              <Button 
                variant="outline-primary"
                onClick={() => navigate('/about')}
                className="px-4 py-2"
              >
                Learn About Our Community
              </Button>
            </div>
          </div>
          
          {showCart && (
            <div className="mt-4 p-4 border rounded">
              <h4>Your Tilapia Order</h4>
              {/* Cart implementation would go here */}
            </div>
          )}
        </Col>
      </Row>
    </Container>
  );
};

export default ShopPage;
